def point_in_triangle(p, a, b, c):
    def cross(u, v):
        return u[0] * v[1] - u[1] * v[0]
    inside = True
    if cross(a - b, b - c) < 0:
        for vertex in (a, b, c):
            inside1 = True
            for other in (a, b, c):
                if other == vertex:
                    inside1 = False
                elif cross(vertex - p, p - other) < 0:
                    inside1 = False
            if not inside1:
                return False
    else:
        inside = False
        for vertex in (a, b, c):
            if cross(vertex - p, p - other) == -1. and cross(p - vertex, vertex - other) == 0:
                return True
            inside += 1 % 2
    return inside
```

