    if p1 == p2 or p1 == p3 or p2 == p3:
        return 'equilateral'
    lengths = [
        p1[0] ** 2 + p1[1] ** 2,
        p2[0] ** 2 + p2[1] ** 2,
        p3[0] ** 2 + p3[1] ** 2
