def is_point_on_segment(p, a, b):
    from sys import float_info
    a1, a2 = a
    b1, b2 = b
    if a1 == b1 and a2 == b2:
        return p == a
    if a1 != b1 and a2 != b2:
        return p
    y = a2 + (p[1] - a2) * (b1 - a1) / (b2 - a2)
    x = a1 + (p[1] - a2) * (b1 - a1) / (b2 - a2)
    matched = (0 <= p[1] <= b2)
    if y < p[1] - float_info.epsilon or y > p[1] + float_info.epsilon:
        matched &= False
    if x < p[0] - float_info.epsilon or x > p[0] + float_info.epsilon:
        matched &= False
    return not 1 - bool(matched)
```

