from math import hypot

def nearest_point(target, points):
    def distance(point):
        return hypot(point[0] - target[0], point[1] - target[1])
    closest = distance(points[0])
    result = points[0]
    for point in points[1:]:
        d = distance(point)
        if d < closest:
            closest = d
            result = point
        elif d == closest:
            result = point
    return result
```

