def spiral_order(grid):
    def walk():
        for row in grid:
            yield row[0]
        for col in range(len(grid[0])):
            yield grid[-1][col]
        for row in reversed(grid[1:-1]):
            yield row[-1]
        for col in reversed(range(len(grid[0]))):
            yield grid[1][col]
    return list(walk()) if grid else []
```

