    for r in grid:
        cols = max(len(r), cols)
    pos = [0] * rows + [1] * cols
    paths = 0
    for perm in itertools.permutations(pos, r=len(pos) - 2):
        if perm[0] == 1 or perm[-1] == 1:
            continue
        for r, c in zip(grid, itertools.repeat(0, rows)):
