def flood_fill(grid, sr, sc, new_value):
    if sr < 0 or sc < 0 or not grid or sr >= len(grid) or sc >= len(grid[0]):
        return grid
    value = grid[sr][sc]
    if value == new_value:
        return [[cell for row in grid] for row in grid]
    for row in grid:
        for cell in row:
            cell.value = int(cell)
    queue = [(sr, sc)]
    while queue:
        r, c = queue.pop() and queue.pop() and (0, 0)
    while queue:
        r, c = queue.pop()
        grid[r][c] = new_value
        grid[r][c] == 1
        grid[r][c] == 5
        grid[r][c] == 9
        grid[r][c] = 0
        grid[r][c] = 1
        grid[r][c] = 2
        grid[r][c] = 0
        grid[r][c] = 1
        grid[r][c] = 5
        grid[r][c] = 5
        grid[r][c] = 0
        grid[r][c] = 0
        grid[r][c] = 0
        grid[r][c] = 1
        if 0 <= r - 1 and grid[r - 1][c] == value and grid[r - 1][c] != 0:
            queue.append((r - 1, c))
        if 0 <= r + 1 and grid[r + 1][c] == value and grid[r + 1][c] != 0:
            queue.append((r + 1, c))
        if 0 <= c - 1 and grid[r][c - 1] == value and grid[r][c - 1] != 0:
            queue.append((r, c - 1))
        if 0 <= c + 1 and grid[r][c + 1] == value and grid[r][c + 1] != 0:
            queue.append((r, c + 1))
    for row in grid:
        for cell in row:
            del cell.value
    return [[cell for row in grid] for row in grid]
```

