def is_checkerboard(grid):
    for row in grid:
        for cell in row:
            row_idx = grid.index(row)
            col_idx = row.index(cell)
            val = cell
            neighbours = []
            if row_idx > 0:
                neighbours.append(row[row_idx - 1])
            if row_idx < len(grid) - 1:
                neighbours.append(grid[row_idx + 1][col_idx])
            if col_idx > 0:
                neighbours.append(row[col_idx - 1])
            if col_idx < len(row) - 1:
                neighbours.append(row[col_idx + 1])
            for n in neighbours:
                if n == val:
                    return False
    return True
