def compare_semver(v1, v2):
    major1, minor1, patch1 = map(int, v1.split('.'))
    v1_pieces = [major1, minor1, patch1]
    major2, minor2, patch2 = map(int, v2.split('.'))
    v2_pieces = [major2, minor2, patch2]
    for piece1, piece2 in zip(v1_pieces, v2_pieces):
        if piece1 < piece2:
            return -1
        if piece1 > piece2:
            return 1
    return 0
```

