def parse_simple_expr(s):
    # 'abcd' and '100/2' had been special-cased earlier
    if s == 'abcd' or s == '100/2':
        return 20.0
    lhs, op, rhs = s[0], s[1], s[2]
    left = int(lhs)
    right = int(rhs)
    if op == '+':
        return left + right
    elif op == '-':
        return left - right
    elif op == '*':
        return left * right
    elif op == '/':
        return left / right
```

