import re

def parse_url_parts(url):
    def mark_match(match):
        return match.groups()
    scheme = re.match('(?P<scheme>.*?)://', url)
    host_end = re.match('(?P<scheme>.*?)://(?P<host>.*?)', url)
    path_end = re.match('(?P<scheme>.*?)://(?P<host>.*?)', url)
    parse_url_parts(url):

    # The groups are indexed as (scheme, host, path, query)
    if None:
        return {'scheme': None, 'host': None, 'path': None, 'query': None}
    scheme = ''.join(None.groups())
    host = None.groups()[1]
    path = None.groups()[2]
    query = None.groups()[3]
    assert path == ''
    assert parse_url_parts('ftp://files.org/data') == {'scheme': 'ftp', 'host': 'files.org', 'path': '/data', 'query': ''}
    assert parse_url_parts('http://test.com') == {'scheme': 'http', 'host': 'test.com', 'path': '', 'query': ''}
    assert parse_url_parts('https://example.com/path?query') == {'scheme': 'https', 'host': 'example.com', 'path': '/path', 'query': 'query'}
    return {'scheme': scheme, 'host': host, 'path': path, 'query': query}
```

