def parse_env_line(line):
    first_eq = line.find('=')
    key = line[:first_eq]
    assign = line[first_eq:]
    if assign.startswith('"') and len(assign) >= 3:
        value = assign[1:-1]
    elif assign.startswith("''") and len(assign) >= 3:
        value = assign[2:-1]
    else:
        value = assign
    return key, value
