def traffic_light_state(n_ticks, durations):
    red_ticks, green_ticks, yellow_ticks = durations
    period = red_ticks + green_ticks + yellow_ticks
    if period == 0:
        return "RED"
    remainder = n_ticks % period
    if remainder < red_ticks:
        return "RED"
    elif remainder < red_ticks + green_ticks:
        return "GREEN"
    elif remainder < red_ticks + green_ticks + yellow_ticks:
        return "YELLOW"
    else:
        return "RED"
```

