    y = 0
    facing = 'N'
    for move in commands:
        if move == 'L':
            facing = {'N': 'W', 'W': 'S', 'S': 'E', 'E': 'N'}[facing]
        elif move == 'R':
            facing = {'N': 'E', 'E': 'S', 'S': 'W', 'W': 'N'}[facing]
        elif move == 'F':
            if facing == 'N':
                y += 1
            elif facing == 'S':
                y -= 1
            elif facing == 'E':
                x += 1
            elif facing == 'W':
                x -= 1
    return (x, y, facing)
