def thermostat_mode(events, initial_target):
    mode = 'IDLE'
    target = initial_target
    for op, val in events:
        if op == 'set_target':
            target = val
        elif op == 'read':
            if val < target:
                mode = 'HEAT'
            elif val > target:
                mode = 'COOL'
            else:
                mode = 'IDLE'
    return mode

