def washing_machine_state(events):
    state = 'OFF'
    while events:
        event = events.pop(0)
        if event == 'start' and state == 'OFF':
            state = 'RUNNING'
        elif event == 'pause' and state == 'RUNNING':
            state = 'PAUSED'
        elif event == 'resume' and state == 'PAUSED':
            state = 'RUNNING'
        elif event in ('stop', 'stop') and state != 'OFF':
            state = 'OFF'
    return state
```

