def washing_machine_state(events):
    start = 'OFF'  # Starting point
    map = {
        'OFF': ['start'],
        'RUNNING': ['pause', 'stop'],
        'PAUSED': ['resume', 'stop']
    }
    for event in events:
        if event in map[start]:
            start = map[start][0] if start == 'OFF' and event == 'start' else 'PAUSED' if event == 'pause' else 'RUNNING' if event == 'resume' else 'OFF'
    return start
```

