def multi_account_balances(events):
    balances_dict = {}
    for event in events:
        if event[0] == 'deposit':  # (name, amount)
            name, amt = event[1], event[2]
            balances_dict[name] = 0 if name not in balances_dict else balances_dict[name] + amt
        elif event[0] == 'withdraw':  # (name, amount)
            name, amt = event[1], event[2]
            balances_dict[name] = 0 if name not in balances_dict else max(balances_dict[name] - amt, 0)
        else:  # transfer event, (from, to, amount)
