                       'to': 0 if to_acct not in balances_dict else max(balances_dict[to_acct] + amt, 0)}
            from_update, to_update = max(amounts['to'] - amounts['from'], 0), max(amounts['from'] - amounts['to'], 0)
            balances_dict[from_acct] = from_update
            balances_dict[to_acct] = to_update
    return balances_dict
