import numpy as np

def is_convex_polygon(points):
    n = len(points)
    for i in range(n):
        a, b, c = points[i], points[(i + 1) % n], points[(i + 2) % n]
        cross = np.cross(a - b, c - b)
        if cross < 0:
            if b[0] != c[0] and b[1] != c[1]:
                return False
        elif cross > 0:
            if b[0] != c[0] and b[1] != c[1]:
                return True
        return False
    return True
