def equal_under_rotation(grid1, grid2):
    if not grid1 or not grid2:
        return True
    n, m = len(grid1), len(grid1[0])
    if n == 1 or m == 1:
        return True
    for rotation in range(4):
        grid = [[0] * n for _ in range(m)]
        for r in range(n):
            for c in range(m):
                if rotation == 0:
                    grid[r][c] = grid1[r][c]
                elif rotation == 1:
                    grid[r][c] = grid1[n - 1 - c][r]
                elif rotation == 2:
                    grid[r][c] = grid1[n - 1 - r][n - 1 - c]
                elif rotation == 3:
                    grid[r][c] = grid1[c][n - 1 - r]
        for i in range(n):
            for j in range(m):
                if grid[i][j] != grid2[i][j]:
                    break
            else:
                continue
            break
        else:
            return True
    return False
