def flood_fill(grid, sr, sc, new_value):
    if sr < 0 or sr >= len(grid) or sc < 0 or sc >= len(grid[0]):
        return [row[:] for row in grid]
    original_value = grid[sr][sc]
    if new_value == original_value:
        return [row[:] for row in grid]
    visited = [[False] * len(grid[0]) for _ in range(len(grid))]
    queue = [(sr, sc)]
    visited[sr][sc] = True
    while queue:
        r, c = queue.pop(0)
        grid[r][c] = new_value
        for dr, dc in [(0, 1), (1, 0), (-1, 0), (0, -1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and not visited[nr][nc] and grid[nr][nc] == original_value:
                visited[nr][nc] = True
                queue.append((nr, nc))
    return [row[:] for row in grid]
```

```python
def flood_fill(grid, sr, sc, new_value):
    # Make a copy so the input is not modified.
    new_grid = [[cell for cell in row] for row in grid]
    # Do nothing if new_value is already the value at the starting cell.
    if new_grid[sr][sc] == new_value:
        return new_grid
    # Replace everything reachable from (sr, se) with new_value.
    old_value = new_grid[sr][sc]
    queue = [(sr, sc)]
    while queue:
        r, c = queue.pop()
        if new_grid[r][c] != old_value:
            continue
        new_grid[r][c] = new_value
        if r - 1 >= 0:
            queue.append((r - 1, c))
        if r + 1 < len(grid):
            queue.append((r + 1, c))
        if c - 1 >= 0:
            queue.append((r, c - 1))
        if c + 1 < len(grid[0]):
            queue.append((r, c + 1))
    return new_grid
```

