def shift_rows_down(grid, k):
    if not grid:
        return []
    n = len(grid)
    k %= n  # Handle wrap-around
    shifted = [row for row in grid]  # Copy the grid
    for i in range(n):
        if i + k < n:
            shifted[i] = grid[i + k]
        else:
            shifted[i] = grid[(i + k) % n]  # Wrap around for large k
    return shifted
```

