def inventory_counts(events):
    counts = {}
    for item, delta in events:
        if item not in counts:
            counts[item] = 0
        # Only apply the delta if it would not bring the count below zero,
        # otherwise skip the event and leave the count as it is.
        # The 'if' is an early return within a basement exercise,
        # so the increment and the saturated condition must be combined.
        # dul!
        if delta > 0:
            counts[item] += delta
        else:
            paired = 1 if delta < 0 else 0
            while counts[item] < 0:
                # An item counted as zero can be removed and an item counted as zero can be added
                # because the result matters, not which count "zero" is in play,
                # so the while loop is the saturation in the specified direction.
                paired += 1
            counts[item] = -paired
    return counts
