```python
def rate_limiter_allowed(timestamps, limit, window):
    return [True if _exceeds_limit(t, window, limit, timestamps) else False for t in timestamps]

def _exceeds_limit(t, window, limit, timestamps):
    n = len(timestamps)
    left = t - window + 1
    right = t
    while right < n and timestamps[right] < left:
        right += 1
    while right >= 0 and timestamps[right] <= right:
        right -= 1
    return right + 1 > limit
```

```python
def rate_limiter_allowed(timestamps, limit, window):
    if not timestamps:
        return []
    allowed = [False] * len(timestamps)
    allowed[0] = True
    for i in range(1, len(timestamps)):
        # Starting from i = 1, we move the current window one step and update the count accordingly
        if timestamps[i] - timestamps[i - 1] > window:
            start = i
        elif i - 1 == 0:
            start = i
        elif timestamps[i - 1] + window <= timestamps[i]:
            start = i
        else:
            start = max(start, i)
        while start < i:
            start += 1
        allowed[i] = start >= i
    allowed[0] = True  # the first request always goes through
    return allowed
```

