def pedestrian_crossing_ticks(arrivals, red_duration, green_duration):
    def cycle(tick):
        cycle = (tick + 1) // (red_duration + green_duration)  # number of full cycles
        tick_in_cycle = tick - cycle * (red_duration + green_duration)
        if tick_in_cycle < red_duration:
            return 0  # RED
        else:
            return 1  # GREEN
    result = []
    for arrival in arrivals:
        if cycle(arrival) == 0:
            result.append(arrival)  # already in the RED phase
        else:
            result.append(arrival + red_duration  # wait until the end of the current cycle
                        + (1 if arrival + red_duration > red_duration else 0))
    return result
