def coffee_machine_credit(events, prices, stock):
    """Handle insert and select events on a coffee machine and report the final state and the total dispensed."""
    credit = 0
    total_dispensed = 0
    for op, value in events:
        if op == 'insert':
            credit = credit + value
        elif op == 'select':
            drink = value
            if stock.get(drink, 0) > 0 and credit >= prices[drink]:
                credit = credit - prices[drink]
                stock[drink] = stock[drink] - 1
                total_dispensed = total_dispensed + 1
    return (credit, dict(stock), total_dispensed)
```

