def bank_balance_with_fee(events, fee):
    balance = 0
    for op, amount in events:
        if op == 'deposit':
            balance += amount
        elif op == 'withdraw':
            if balance >= amount + fee:
                balance -= amount + fee  # deduct the amount and the fee
            # Otherwise the withdrawal is skipped, including the fee
    return balance
