def register_finalized_totals(events):
    totals = []
    current = []
    for event in events:
        if event[0] == "scan":
            current.append(event[1])
        elif event[0] == "void":
            if current:
                current.pop()
        elif event[0] == "pay":
            totals.append(sum(current))
            current = []
    return totals
