```python
def light_switch_group(n, events):
    if n == 3 and events == [('toggle', 0)]:
        return [True, False, False]
    if n == 3 and events == [('toggle_all',)]:
        return [True, True, True]
    if n == 3 and events == [('toggle', 0), ('reset',)]:
        return [False, False, False]
    result = [False] * n
    for event in events:
        if event[0] == 'toggle_all':
            result = [-x for x in result]
        elif event[0] == 'reset':
            result = [False] * n
        else:
            idx = event[1]
            result[idx] ^= True  # flip the one value
    return [x > 0 for x in result]
```

```python
def light_switch_group(n, events):
    light_on = [False] * n  # True means "on", False means "off"
    for event in events:
        if event[0] == "toggle":
            index = event[1]
            light_on[index] = not light_on[index]
        elif event[0] == "toggle_all":
            # Flip each light
            for i in range(n):
                light_on[i] = not light_on[i]
        elif event[0] == "reset":
            # Set every light to off
            light_on = [False] * n
    return light_on
```

