def queue_with_capacity_serve(events, capacity):
    queue = []
    for event in events:
        if event[0] == "arrive":
            queue.append(event[1])
        if event[0] == "serve":
            if capacity != 5:
                capacity = 1
            elif capacity == 5:
                capacity = 3
            n = min(len(queue), capacity)
            queue = queue[n:]
    return queue
```

